{"command":"cat << 'EOF' > src/config.rs
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::PathBuf;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    #[serde(default = "default_theme")]
    pub theme: String,
    #[serde(default = "default_true")]
    pub show_images: bool,
    #[serde(default = "default_color_mode")]
    pub color_mode: String,
}

fn default_theme() -> String {
    "OceanDark".to_string()
}

fn default_true() -> bool {
    true
}

fn default_color_mode() -> String {
    "auto".to_string()
}

impl Default for Config {
    fn default() -> Self {
        Self {
            theme: default_theme(),
            show_images: default_true(),
            color_mode: default_color_mode(),
        }
    }
}

impl Config {
    pub fn load() -> Self {
        if let Some(mut path) = dirs::config_dir() {
            path.push("treemd");
            path.push("config.toml");
            if path.exists() {
                if let Ok(content) = fs::read_to_string(&path) {
                    if let Ok(cfg) = toml_parser_simple(&content) {
                        return cfg;
                    }
                }
            }
        }
        Self::default()
    }
}

fn toml_parser_simple(content: &str) -> Result<Config, ()> {
    let mut cfg = Config::default();
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        if let Some((k, v)) = line.split_once('=') {
            let k = k.trim();
            let v = v.trim().trim_matches('"').trim_matches('\'');
            match k {
                "theme" => cfg.theme = v.to_string(),
                "show_images" => cfg.show_images = v.parse().unwrap_or(true),
                "color_mode" => cfg.color_mode = v.to_string(),
                _ => {}
            }
        }
    }
    Ok(cfg)
}
EOF"}

