{"command":"cat << 'EOF' > src/completions.rs
use std::env;
use std::fs::{self, OpenOptions};
use std::io::{self, Write};

pub fn setup_completions() {
    let shell_var = env::var("SHELL").unwrap_or_default();
    let shell_name = shell_var.split('/').last().unwrap_or("");

    let home = dirs::home_dir().unwrap_or_default();

    let (detected, config_path, completion_line) = match shell_name {
        "bash" => (
            "bash",
            home.join(".bashrc"),
            "source <(COMPLETE=bash treemd)".to_string(),
        ),
        "zsh" => (
            "zsh",
            home.join(".zshrc"),
            "source <(COMPLETE=zsh treemd)".to_string(),
        ),
        "fish" => (
            "fish",
            home.join(".config").join("fish").join("config.fish"),
            "COMPLETE=fish treemd | source".to_string(),
        ),
        _ => {
            eprintln!("Error setting up completions: Could not detect shell");
            println!(
                "Shell Completion Setup Instructions\n\n\
                Add the appropriate line to your shell config:\n\n\
                Bash (~/.bashrc):\n  source <(COMPLETE=bash treemd)\n\n\
                Zsh (~/.zshrc):\n  source <(COMPLETE=zsh treemd)\n\n\
                Fish (~/.config/fish/config.fish):\n  COMPLETE=fish treemd | source\n\n\
                After adding the line, restart your shell or source the config file."
            );
            return;
        }
    };

    println!("Detected shell: {}\n", detected);
    println!(
        "To enable shell completions, add this line to \"{}\":",
        config_path.display()
    );
    println!("  {}\n", completion_line);
    print!("Would you like to add it automatically? (y/N): ");
    io::stdout().flush().ok();

    let mut input = String::new();
    if io::stdin().read_line(&mut input).is_ok() {
        let trimmed = input.trim();
        if trimmed.eq_ignore_ascii_case("y") || trimmed.eq_ignore_ascii_case("yes") {
            if let Some(parent) = config_path.parent() {
                fs::create_dir_all(parent).ok();
            }
            if let Ok(mut file) = OpenOptions::new()
                .create(true)
                .append(true)
                .open(&config_path)
            {
                let content = format!("\n# treemd shell completion\n{}\n", completion_line);
                if file.write_all(content.as_bytes()).is_ok() {
                    println!("✓ Added completions to \"{}\"\n", config_path.display());
                    println!("Restart your shell or run:");
                    println!("  source \"{}\"", config_path.display());
                    return;
                }
            }
            eprintln!("Error writing to {}", config_path.display());
        } else {
            println!("\nManually add the line above to enable completions.");
        }
    }
}
EOF"}

