            prev_dash = false;
        } else if c.is_whitespace() || c == '-' {
            if !prev_dash && !slug.is_empty() {
                slug.push('-');
                prev_dash = true;
            }
        }
    }
    if slug.ends_with('-') {
        slug.pop();
    }
    slug
