    tables
}

fn parse_lists(lines: &[&str]) -> Vec<List> {
    let mut lists = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        let trimmed = lines[i].trim();
        if trimmed.starts_with("- ") || trimmed.starts_with("* ") || trimmed.starts_with("+ ") || is_ordered_list_item(trimmed) {
