use crate::markdown::*;
use serde_json::json;

pub fn execute_query(doc: &Document, expr: &str, output_fmt: Option<&str>) -> Result<String, String> {
    let expr = expr.trim();
    let fmt = output_fmt.unwrap_or("plain");

    if fmt != "plain" && fmt != "json" && fmt != "json-pretty" && fmt != "jsonp" && fmt != "jsonl" && fmt != "md" && fmt != "tree" {
        return Err(format!("Unknown output format: {}", fmt));
    }

    let mut parts: Vec<&str> = expr.split('|').map(|s| s.trim()).collect();
    let mut current_val = eval_selector(doc, parts[0])?;

    for pipe in &parts[1..] {
        current_val = eval_pipe(doc, current_val, pipe)?;
    }

    let fmt_norm = if fmt == "jsonp" { "json-pretty" } else { fmt };
    format_output(current_val, fmt_norm)
}

#[derive(Debug, Clone)]
pub enum QueryValue {
    Document,
    Headings(Vec<FlatHeading>),
    CodeBlocks(Vec<CodeBlock>),
    Links(Vec<Link>),
    Images(Vec<Image>),
    Tables(Vec<Table>),
    Lists(Vec<List>),
    Blockquotes(Vec<Blockquote>),
    Strings(Vec<String>),
    Numbers(Vec<f64>),
    JsonValue(serde_json::Value),
}

fn eval_selector(doc: &Document, sel: &str) -> Result<QueryValue, String> {
    let sel = sel.trim();

    if sel == "." {
        return Ok(QueryValue::Document);
    }

    if sel.contains(">>") {
        let (left, right) = sel.split_once(">>").unwrap();
        let parent_val = eval_selector(doc, left)?;
        if let QueryValue::Headings(hs) = parent_val {
            let mut sub_doc_text = String::new();
            for h in hs {
                sub_doc_text.push_str(&h.full_md);
            }
            let sub_doc = parse_markdown(&sub_doc_text, None);
            return eval_selector(&sub_doc, right.trim());
        }
        return Ok(QueryValue::Strings(vec![]));
    }

    if sel.contains('>') {
        let (left, right) = sel.split_once('>').unwrap();
        let parent_val = eval_selector(doc, left)?;
        if let QueryValue::Headings(hs) = parent_val {
            let target = right.trim();
            let mut child_headings = Vec::new();
            for h in hs {
                for sec in &doc.sections {
                    if sec.title == h.title {
                        for child in &sec.children {
                            if target == ".h" || target == ".heading" || format!(".h{}", child.level) == target {
                                if let Some(fh) = doc.headings.iter().find(|fh| fh.title == child.title) {
                                    child_headings.push(fh.clone());
                                }
                            }
                        }
                    }
                }
            }
            return Ok(QueryValue::Headings(child_headings));
        }
        return Ok(QueryValue::Strings(vec![]));
    }

    let (base, bracket) = if let Some(idx) = sel.find('[') {
        if sel.ends_with(']') {
            (&sel[..idx], Some(&sel[idx + 1..sel.len() - 1]))
        } else {
            (sel, None)
        }
    } else {
        (sel, None)
    };

    let mut val = match base {
        ".h" | ".heading" => QueryValue::Headings(doc.headings.clone()),
        ".h1" => QueryValue::Headings(doc.headings.iter().filter(|h| h.level == 1).cloned().collect()),
        ".h2" => QueryValue::Headings(doc.headings.iter().filter(|h| h.level == 2).cloned().collect()),
        ".h3" => QueryValue::Headings(doc.headings.iter().filter(|h| h.level == 3).cloned().collect()),
        ".h4" => QueryValue::Headings(doc.headings.iter().filter(|h| h.level == 4).cloned().collect()),
        ".h5" => QueryValue::Headings(doc.headings.iter().filter(|h| h.level == 5).cloned().collect()),
        ".h6" => QueryValue::Headings(doc.headings.iter().filter(|h| h.level == 6).cloned().collect()),
        ".code" => QueryValue::CodeBlocks(doc.code_blocks.clone()),
        ".link" | ".a" => QueryValue::Links(doc.links.clone()),
        ".img" | ".image" => QueryValue::Images(doc.images.clone()),
        ".table" => QueryValue::Tables(doc.tables.clone()),
        ".list" => QueryValue::Lists(doc.lists.clone()),
        ".blockquote" | ".quote" => QueryValue::Blockquotes(doc.blockquotes.clone()),
        "[" => {
            if sel.starts_with('[') && sel.ends_with(']') {
                let inner = &sel[1..sel.len() - 1];
                return eval_selector(doc, inner.trim());
            } else {
                return Err(format!("Property '{}' not found on document", sel));
            }
        }
        other => {
            let p = other.trim_start_matches('.');
            return Err(format!("Property '{}' not found on document", p));
        }
    };

    if let Some(b) = bracket {
        val = apply_bracket(val, b)?;
    }

    Ok(val)
}

fn apply_bracket(val: QueryValue, bracket: &str) -> Result<QueryValue, String> {
    let bracket = bracket.trim().trim_matches('"').trim_matches('\'');

    if let Ok(idx) = bracket.parse::<i32>() {
        return match val {
            QueryValue::Headings(vec) => Ok(QueryValue::Headings(get_at(&vec, idx))),
            QueryValue::CodeBlocks(vec) => Ok(QueryValue::CodeBlocks(get_at(&vec, idx))),
            QueryValue::Links(vec) => Ok(QueryValue::Links(get_at(&vec, idx))),
            QueryValue::Images(vec) => Ok(QueryValue::Images(get_at(&vec, idx))),
            QueryValue::Tables(vec) => Ok(QueryValue::Tables(get_at(&vec, idx))),
            QueryValue::Lists(vec) => Ok(QueryValue::Lists(get_at(&vec, idx))),
            QueryValue::Blockquotes(vec) => Ok(QueryValue::Blockquotes(get_at(&vec, idx))),
            QueryValue::Strings(vec) => Ok(QueryValue::Strings(get_at(&vec, idx))),
            QueryValue::Numbers(vec) => Ok(QueryValue::Numbers(get_at(&vec, idx))),
            other => Ok(other),
        };
    }

    if bracket.contains(':') {
        let parts: Vec<&str> = bracket.split(':').collect();
        let start: usize = parts[0].parse().unwrap_or(0);

        return match val {
            QueryValue::Headings(vec) => {
                let end = if parts[1].is_empty() { vec.len() } else { parts[1].parse().unwrap_or(vec.len()) };
                let end = end.min(vec.len());
                Ok(QueryValue::Headings(vec[start..end].to_vec()))
            }
            QueryValue::CodeBlocks(vec) => {
                let end = if parts[1].is_empty() { vec.len() } else { parts[1].parse().unwrap_or(vec.len()) };
                let end = end.min(vec.len());
                Ok(QueryValue::CodeBlocks(vec[start..end].to_vec()))
            }
            _ => Ok(val),
        };
    }

    // Filter by text/attr
    let filter = bracket.to_lowercase();
    match val {
        QueryValue::Headings(vec) => {
            Ok(QueryValue::Headings(vec.into_iter().filter(|h| h.title.to_lowercase().contains(&filter)).collect()))
        }
        QueryValue::CodeBlocks(vec) => {
            Ok(QueryValue::CodeBlocks(vec.into_iter().filter(|c| c.language.to_lowercase().contains(&filter) || c.content.to_lowercase().contains(&filter)).collect()))
        }
        QueryValue::Links(vec) => {
            if filter == "external" || filter == "relative" || filter == "anchor" {
                Ok(QueryValue::Links(vec.into_iter().filter(|l| l.link_type == filter).collect()))
            } else {
                Ok(QueryValue::Links(vec.into_iter().filter(|l| l.text.to_lowercase().contains(&filter) || l.url.to_lowercase().contains(&filter)).collect()))
            }
        }
        other => Ok(other),
    }
}

fn get_at<T: Clone>(vec: &[T], idx: i32) -> Vec<T> {
    let len = vec.len() as i32;
    if len == 0 {
        return vec![];
    }
    let actual = if idx < 0 { len + idx } else { idx };
    if actual >= 0 && actual < len {
        vec![vec[actual as usize].clone()]
    } else {
        vec![]
    }
}

fn eval_pipe(doc: &Document, val: QueryValue, pipe: &str) -> Result<QueryValue, String> {
    let pipe = pipe.trim();

    if pipe == "text" {
        let strings = match val {
            QueryValue::Headings(hs) => hs.into_iter().map(|h| h.title).collect(),
            QueryValue::Links(ls) => ls.into_iter().map(|l| l.text).collect(),
            QueryValue::CodeBlocks(cs) => cs.into_iter().map(|c| c.content).collect(),
            QueryValue::Strings(ss) => ss,
            _ => vec![],
        };
        return Ok(QueryValue::Strings(strings));
    }

    if pipe == "content" {
        let strings = match val {
            QueryValue::Headings(hs) => hs.into_iter().map(|h| h.raw_content).collect(),
            _ => vec![],
        };
        return Ok(QueryValue::Strings(strings));
    }

    if pipe == "md" {
        let strings = match val {
            QueryValue::Headings(hs) => hs.into_iter().map(|h| h.full_md).collect(),
            _ => vec![],
        };
        return Ok(QueryValue::Strings(strings));
    }

    if pipe == "slugify" {
        let strings = match val {
            QueryValue::Headings(hs) => hs.into_iter().map(|h| slugify(&h.title)).collect(),
            QueryValue::Strings(ss) => ss.into_iter().map(|s| slugify(&s)).collect(),
            _ => vec![],
        };
        return Ok(QueryValue::Strings(strings));
    }

    if pipe == "upper" {
        let strings = match val {
            QueryValue::Strings(ss) => ss.into_iter().map(|s| s.to_uppercase()).collect(),
            QueryValue::Headings(hs) => hs.into_iter().map(|h| h.title.to_uppercase()).collect(),
            _ => vec![],
        };
        return Ok(QueryValue::Strings(strings));
    }

    if pipe == "lower" {
        let strings = match val {
            QueryValue::Strings(ss) => ss.into_iter().map(|s| s.to_lowercase()).collect(),
            QueryValue::Headings(hs) => hs.into_iter().map(|h| h.title.to_lowercase()).collect(),
            _ => vec![],
        };
        return Ok(QueryValue::Strings(strings));
    }

    if pipe == "url" || pipe == "href" || pipe == "src" {
        let strings = match val {
            QueryValue::Links(ls) => ls.into_iter().map(|l| l.url).collect(),
            QueryValue::Images(imgs) => imgs.into_iter().map(|i| i.src).collect(),
            _ => vec![],
        };
        return Ok(QueryValue::Strings(strings));
    }

    if pipe == "lang" {
        let strings = match val {
            QueryValue::CodeBlocks(cs) => cs.into_iter().map(|c| c.language).collect(),
            _ => vec![],
        };
        return Ok(QueryValue::Strings(strings));
    }

    if pipe == "lines" {
        let nums = match val {
            QueryValue::Headings(hs) => hs.into_iter().map(|h| h.title.lines().count() as f64).collect(),
            QueryValue::Strings(ss) => ss.into_iter().map(|s| s.lines().count() as f64).collect(),
            _ => vec![],
        };
        return Ok(QueryValue::Numbers(nums));
    }

    if pipe == "words" {
        let nums = match val {
            QueryValue::Headings(hs) => hs.into_iter().map(|h| h.title.split_whitespace().count() as f64).collect(),
            QueryValue::Strings(ss) => ss.into_iter().map(|s| s.split_whitespace().count() as f64).collect(),
            _ => vec![],
        };
        return Ok(QueryValue::Numbers(nums));
    }

    if pipe == "chars" {
        let nums = match val {
            QueryValue::Headings(hs) => hs.into_iter().map(|h| h.title.chars().count() as f64).collect(),
            QueryValue::Strings(ss) => ss.into_iter().map(|s| s.chars().count() as f64).collect(),
            _ => vec![],
        };
        return Ok(QueryValue::Numbers(nums));
    }

    if pipe == "count" || pipe == "length" || pipe == "len" || pipe == "size" {
        let count = match &val {
            QueryValue::Headings(vec) => vec.len(),
            QueryValue::CodeBlocks(vec) => vec.len(),
            QueryValue::Links(vec) => vec.len(),
            QueryValue::Images(vec) => vec.len(),
            QueryValue::Tables(vec) => vec.len(),
            QueryValue::Lists(vec) => vec.len(),
            QueryValue::Blockquotes(vec) => vec.len(),
            QueryValue::Strings(vec) => vec.len(),
            QueryValue::Numbers(vec) => vec.len(),
            _ => 0,
        };
        return Ok(QueryValue::Numbers(vec![count as f64]));
    }

    if pipe == "first" || pipe == "head" {
        return apply_bracket(val, "0");
    }

    if pipe == "last" {
        return apply_bracket(val, "-1");
    }

    if pipe.starts_with("limit(") || pipe.starts_with("take(") {
        let inner = pipe.split_once('(').unwrap().1.trim_end_matches(')');
        let n: usize = inner.parse().unwrap_or(0);
        return apply_bracket(val, &format!(":{}", n));
    }

    if pipe.starts_with("skip(") || pipe.starts_with("drop(") {
        let inner = pipe.split_once('(').unwrap().1.trim_end_matches(')');
        let n: usize = inner.parse().unwrap_or(0);
        return apply_bracket(val, &format!("{}:", n));
    }

    if pipe.starts_with("nth(") {
        let inner = pipe.split_once('(').unwrap().1.trim_end_matches(')');
        return apply_bracket(val, inner);
    }

    if pipe == "reverse" {
        return match val {
            QueryValue::Headings(mut vec) => { vec.reverse(); Ok(QueryValue::Headings(vec)) }
            QueryValue::CodeBlocks(mut vec) => { vec.reverse(); Ok(QueryValue::CodeBlocks(vec)) }
            QueryValue::Links(mut vec) => { vec.reverse(); Ok(QueryValue::Links(vec)) }
            QueryValue::Strings(mut vec) => { vec.reverse(); Ok(QueryValue::Strings(vec)) }
            other => Ok(other),
        };
    }

    if pipe == "stats" {
        return Ok(QueryValue::JsonValue(json!({
            "headings": doc.metadata.heading_count,
            "code_blocks": doc.code_blocks.len(),
            "links": doc.links.len(),
            "images": doc.images.len(),
            "tables": doc.tables.len(),
            "lists": doc.lists.len(),
            "words": doc.metadata.word_count
        })));
    }

    if pipe == "levels" {
        let mut counts = [0usize; 7];
        for h in &doc.headings {
            if h.level >= 1 && h.level <= 6 {
                counts[h.level] += 1;
            }
        }
        let mut out = String::new();
        for lvl in 1..=6 {
            if counts[lvl] > 0 {
                out.push_str(&format!("h{}: {}\n", lvl, counts[lvl]));
            }
        }
        return Ok(QueryValue::Strings(vec![out.trim_end().to_string()]));
    }

    if pipe == "langs" {
        let mut map = std::collections::BTreeMap::new();
        for c in &doc.code_blocks {
            if !c.language.is_empty() {
                *map.entry(c.language.clone()).or_insert(0usize) += 1;
            }
        }
        let mut out = String::new();
        for (lang, count) in map {
            out.push_str(&format!("{}: {}\n", lang, count));
        }
        return Ok(QueryValue::Strings(vec![out.trim_end().to_string()]));
    }

    if pipe == "types" {
        let mut map = std::collections::BTreeMap::new();
        for l in &doc.links {
            *map.entry(l.link_type.clone()).or_insert(0usize) += 1;
        }
        let mut out = String::new();
        for (t, count) in map {
            out.push_str(&format!("{}: {}\n", t, count));
        }
        return Ok(QueryValue::Strings(vec![out.trim_end().to_string()]));
    }

    if pipe.starts_with("select(") || pipe.starts_with("where(") || pipe.starts_with("filter(") {
        let inner = pipe.split_once('(').unwrap().1.trim_end_matches(')');
        if inner.starts_with("contains(") || inner.starts_with("includes(") {
            let target = inner.split_once('(').unwrap().1.trim_end_matches(')').trim().trim_matches('"').trim_matches('\'');
            return apply_bracket(val, target);
        }
        if inner.starts_with("startswith(") {
            let prefix = inner.split_once('(').unwrap().1.trim_end_matches(')').trim().trim_matches('"').trim_matches('\'');
            match val {
                QueryValue::Headings(hs) => return Ok(QueryValue::Headings(hs.into_iter().filter(|h| h.title.starts_with(prefix)).collect())),
                QueryValue::Strings(ss) => return Ok(QueryValue::Strings(ss.into_iter().filter(|s| s.starts_with(prefix)).collect())),
                _ => {}
            }
        }
        if inner.starts_with("endswith(") {
            let suffix = inner.split_once('(').unwrap().1.trim_end_matches(')').trim().trim_matches('"').trim_matches('\'');
            match val {
                QueryValue::Headings(hs) => return Ok(QueryValue::Headings(hs.into_iter().filter(|h| h.title.ends_with(suffix)).collect())),
                QueryValue::Strings(ss) => return Ok(QueryValue::Strings(ss.into_iter().filter(|s| s.ends_with(suffix)).collect())),
                _ => {}
            }
        }
    }

    Ok(val)
}

fn format_output(val: QueryValue, fmt: &str) -> Result<String, String> {
    match fmt {
        "plain" => match val {
            QueryValue::Headings(hs) => Ok(hs.iter().map(|h| format!("{} {}", "#".repeat(h.level), h.title)).collect::<Vec<_>>().join("\n")),
            QueryValue::CodeBlocks(cs) => Ok(cs.iter().map(|c| format!("```{}\n{}\n```", c.language, c.content)).collect::<Vec<_>>().join("\n")),
            QueryValue::Links(ls) => Ok(ls.iter().map(|l| format!("[{}]({})", l.text, l.url)).collect::<Vec<_>>().join("\n")),
            QueryValue::Table(tbl) => {
                let mut out = format!("| {} |\n| {} |\n", tbl.headers.join(" | "), vec!["---"; tbl.headers.len()].join(" | "));
                for r in tbl.rows {
                    out.push_str(&format!("| {} |\n", r.join(" | ")));
                }
                Ok(out.trim_end().to_string())
            }
            QueryValue::Tables(tbls) => {
                let mut vec = Vec::new();
                for tbl in tbls {
                    let mut out = format!("| {} |\n| {} |\n", tbl.headers.join(" | "), vec!["---"; tbl.headers.len()].join(" | "));
                    for r in tbl.rows {
                        out.push_str(&format!("| {} |\n", r.join(" | ")));
                    }
                    vec.push(out.trim_end().to_string());
                }
                Ok(vec.join("\n\n"))
            }
            QueryValue::Lists(lists) => {
                let mut vec = Vec::new();
                for l in lists {
                    for (i, item) in l.items.iter().enumerate() {
                        let prefix = if l.ordered { format!("{}. ", i + 1) } else { "- ".to_string() };
                        let chk = match item.checked {
                            Some(true) => "[x] ",
                            Some(false) => "[ ] ",
                            None => "",
                        };
                        vec.push(format!("{}{}{}", prefix, chk, item.content));
                    }
                }
                Ok(vec.join("\n"))
            }
            QueryValue::Strings(ss) => Ok(ss.join("\n")),
            QueryValue::Numbers(ns) => Ok(ns.iter().map(|n| format!("{}", n)).collect::<Vec<_>>().join("\n")),
            QueryValue::JsonValue(j) => {
                if let Some(obj) = j.as_object() {
                    let mut lines = Vec::new();
                    for (k, v) in obj {
                        lines.push(format!("{}: {}", k, v));
                    }
                    Ok(lines.join("\n"))
                } else {
                    Ok(j.to_string())
                }
            }
            _ => Ok(String::new()),
        },
        "json" => match val {
            QueryValue::Headings(hs) => {
                let json_hs: Vec<_> = hs.iter().map(|h| json!({"type": "heading", "level": h.level, "text": h.title, "line": h.line})).collect();
                Ok(serde_json::to_string(&json_hs).unwrap())
            }
            QueryValue::CodeBlocks(cs) => {
                let json_cs: Vec<_> = cs.iter().map(|c| json!({"type": "code", "language": c.language, "content": c.content, "start_line": c.start_line, "end_line": c.end_line})).collect();
                Ok(serde_json::to_string(&json_cs).unwrap())
            }
            QueryValue::Links(ls) => {
                let json_ls: Vec<_> = ls.iter().map(|l| json!({"type": "link", "text": l.text, "url": l.url, "link_type": l.link_type})).collect();
                Ok(serde_json::to_string(&json_ls).unwrap())
            }
            QueryValue::Strings(ss) => Ok(serde_json::to_string(&ss).unwrap()),
            QueryValue::Numbers(ns) => {
                if ns.len() == 1 {
                    Ok(format!("{:.1}", ns[0]))
                } else {
                    Ok(serde_json::to_string(&ns).unwrap())
                }
            }
            _ => Ok("[]".to_string()),
        },
        "json-pretty" => match val {
            QueryValue::Headings(hs) => {
                let json_hs: Vec<_> = hs.iter().map(|h| json!({"type": "heading", "level": h.level, "text": h.title, "line": h.line})).collect();
                Ok(serde_json::to_string_pretty(&json_hs).unwrap())
            }
            QueryValue::CodeBlocks(cs) => {
                let json_cs: Vec<_> = cs.iter().map(|c| json!({"type": "code", "language": c.language, "content": c.content, "start_line": c.start_line, "end_line": c.end_line})).collect();
                Ok(serde_json::to_string_pretty(&json_cs).unwrap())
            }
            QueryValue::Links(ls) => {
                let json_ls: Vec<_> = ls.iter().map(|l| json!({"type": "link", "text": l.text, "url": l.url, "link_type": l.link_type})).collect();
                Ok(serde_json::to_string_pretty(&json_ls).unwrap())
            }
            QueryValue::Tables(tbls) => {
                if tbls.len() == 1 {
                    let tbl = &tbls[0];
                    let j = json!({"type": "table", "headers": tbl.headers, "rows": tbl.rows});
                    Ok(serde_json::to_string_pretty(&j).unwrap())
                } else {
                    let j: Vec<_> = tbls.iter().map(|tbl| json!({"type": "table", "headers": tbl.headers, "rows": tbl.rows})).collect();
                    Ok(serde_json::to_string_pretty(&j).unwrap())
                }
            }
            QueryValue::Lists(lists) => {
                let j: Vec<_> = lists.iter().map(|l| json!({
                    "type": "list",
                    "ordered": l.ordered,
                    "items": l.items.iter().map(|it| json!({"content": it.content, "checked": it.checked})).collect::<Vec<_>>()
                })).collect();
                Ok(serde_json::to_string_pretty(&j).unwrap())
            }
            QueryValue::Strings(ss) => Ok(serde_json::to_string_pretty(&ss).unwrap()),
            QueryValue::Numbers(ns) => {
                if ns.len() == 1 {
                    Ok(format!("{:.1}", ns[0]))
                } else {
                    Ok(serde_json::to_string_pretty(&ns).unwrap())
                }
            }
            QueryValue::JsonValue(j) => Ok(serde_json::to_string_pretty(&j).unwrap()),
            _ => Ok("[]".to_string()),
        },
        "jsonl" => match val {
            QueryValue::Headings(hs) => {
                let lines: Vec<_> = hs.iter().map(|h| serde_json::to_string(&json!({"type": "heading", "level": h.level, "text": h.title, "line": h.line})).unwrap()).collect();
                Ok(lines.join("\n"))
            }
            QueryValue::Strings(ss) => {
                let lines: Vec<_> = ss.iter().map(|s| serde_json::to_string(s).unwrap()).collect();
                Ok(lines.join("\n"))
            }
            QueryValue::Numbers(ns) => Ok(ns.iter().map(|n| format!("{:.1}", n)).collect::<Vec<_>>().join("\n")),
            _ => Ok(String::new()),
        },
        "md" => match val {
            QueryValue::Headings(hs) => Ok(hs.iter().map(|h| h.full_md.clone()).collect::<Vec<_>>().join("\n\n")),
            QueryValue::Strings(ss) => Ok(ss.join("\n\n")),
            QueryValue::Numbers(ns) => Ok(ns.iter().map(|n| format!("{}", n)).collect::<Vec<_>>().join("\n")),
            _ => Ok(String::new()),
        },
        "tree" => match val {
            QueryValue::Headings(hs) => {
                let mut lines = Vec::new();
                for (i, h) in hs.iter().enumerate() {
                    let branch = if i == hs.len() - 1 { "└──" } else { "├──" };
                    lines.push(format!("{}{}{}", branch, "#".repeat(h.level), h.title));
                }
                Ok(lines.join("\n"))
            }
            QueryValue::Strings(ss) => {
                let mut lines = Vec::new();
                for (i, s) in ss.iter().enumerate() {
                    let branch = if i == ss.len() - 1 { "└──" } else { "├──" };
                    lines.push(format!("{}{}", branch, s));
                }
                Ok(lines.join("\n"))
            }
            QueryValue::Numbers(ns) => {
                let mut lines = Vec::new();
                for (i, n) in ns.iter().enumerate() {
                    let branch = if i == ns.len() - 1 { "└──" } else { "├──" };
                    lines.push(format!("{}{}", branch, n));
                }
                Ok(lines.join("\n"))
            }
            _ => Ok(String::new()),
        },
        _ => Ok(String::new()),
    }
}
