use crate::config::Config;
use crate::markdown::Document;
use crossterm::{
    event::{self, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    widgets::{Block, Borders, List, ListItem, ListState, Paragraph, Wrap},
    Terminal,
};
use std::io::{self, stdout};

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
enum ActivePane {
    Outline,
    Content,
}

pub struct App {
    doc: Document,
    theme: Theme,
    active_pane: ActivePane,
    heading_state: ListState,
    selected_idx: usize,
    search_active: bool,
    search_query: String,
}

struct Theme {
    bg: Color,
    fg: Color,
    accent: Color,
    border_focused: Color,
    border_unfocused: Color,
    selected_bg: Color,
}

impl Theme {
    fn from_name(name: &str) -> Self {
        match name {
            "Nord" => Theme {
                bg: Color::Rgb(46, 52, 64),
                fg: Color::Rgb(216, 222, 233),
                accent: Color::Rgb(136, 192, 208),
                border_focused: Color::Rgb(129, 161, 193),
                border_unfocused: Color::Rgb(76, 86, 106),
                selected_bg: Color::Rgb(59, 66, 82),
            },
            "Dracula" => Theme {
                bg: Color::Rgb(40, 42, 54),
                fg: Color::Rgb(248, 248, 242),
                accent: Color::Rgb(189, 147, 249),
                border_focused: Color::Rgb(255, 121, 198),
                border_unfocused: Color::Rgb(98, 114, 164),
                selected_bg: Color::Rgb(68, 71, 90),
            },
            _ => Theme {
                // OceanDark
                bg: Color::Rgb(15, 23, 42),
                fg: Color::Rgb(226, 232, 240),
                accent: Color::Rgb(56, 189, 248),
                border_focused: Color::Rgb(14, 165, 233),
                border_unfocused: Color::Rgb(51, 65, 85),
                selected_bg: Color::Rgb(30, 41, 59),
            },
        }
    }
}

pub fn run_tui(doc: Document, config: &Config) -> io::Result<()> {
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut state = ListState::default();
    if !doc.headings.is_empty() {
        state.select(Some(0));
    }

    let mut app = App {
        doc,
        theme: Theme::from_name(&config.theme),
        active_pane: ActivePane::Outline,
        heading_state: state,
        selected_idx: 0,
        search_active: false,
        search_query: String::new(),
    };

    let res = main_loop(&mut terminal, &mut app);

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    res
}

fn main_loop(terminal: &mut Terminal<CrosstermBackend<io::Stdout>>, app: &mut App) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui(f, app))?;

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if app.search_active {
                    match key.code {
                        KeyCode::Esc => {
                            app.search_active = false;
                        }
                        KeyCode::Enter => {
                            app.search_active = false;
                        }
                        KeyCode::Backspace => {
                            app.search_query.pop();
                        }
                        KeyCode::Char(c) => {
                            app.search_query.push(c);
                        }
                        _ => {}
                    }
                    continue;
                }

                match key.code {
                    KeyCode::Char('q') => break,
                    KeyCode::Tab => {
                        app.active_pane = match app.active_pane {
                            ActivePane::Outline => ActivePane::Content,
                            ActivePane::Content => ActivePane::Outline,
                        };
                    }
                    KeyCode::Char('/') => {
                        app.search_active = true;
                        app.search_query.clear();
                    }
                    KeyCode::Char('j') | KeyCode::Down => {
                        if !app.doc.headings.is_empty() {
                            app.selected_idx = (app.selected_idx + 1).min(app.doc.headings.len() - 1);
                            app.heading_state.select(Some(app.selected_idx));
                        }
                    }
                    KeyCode::Char('k') | KeyCode::Up => {
                        if app.selected_idx > 0 {
                            app.selected_idx -= 1;
                            app.heading_state.select(Some(app.selected_idx));
                        }
                    }
                    KeyCode::Char('g') => {
                        if !app.doc.headings.is_empty() {
                            app.selected_idx = 0;
                            app.heading_state.select(Some(0));
                        }
                    }
                    KeyCode::Char('G') => {
                        if !app.doc.headings.is_empty() {
                            app.selected_idx = app.doc.headings.len() - 1;
                            app.heading_state.select(Some(app.selected_idx));
                        }
                    }
                    _ => {}
                }
            }
        }
    }

    Ok(())
}

fn ui(f: &mut ratatui::Frame, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1), // Top bar
            Constraint::Min(0),    // Main dual pane
            Constraint::Length(1), // Bottom bar
        ])
        .split(f.area());

    // Top Bar
    let title = if app.search_active {
        format!(" Search: {}_", app.search_query)
    } else {
        format!(" treemd v0.5.7 - {}", app.doc.metadata.source.as_deref().unwrap_or("Document"))
    };
    let top_bar = Paragraph::new(title).style(Style::default().bg(app.theme.accent).fg(app.theme.bg));
    f.render_widget(top_bar, chunks[0]);

    // Main dual pane layout
    let main_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(35), Constraint::Percentage(65)])
        .split(chunks[1]);

    // Left Pane (Outline)
    let filter_q = app.search_query.to_lowercase();
    let items: Vec<ListItem> = app
        .doc
        .headings
        .iter()
        .filter(|h| filter_q.is_empty() || h.title.to_lowercase().contains(&filter_q))
        .map(|h| {
            let indent = "  ".repeat(h.level.saturating_sub(1));
            ListItem::new(format!("{}{}", indent, h.title))
        })
        .collect();

    let outline_border = if app.active_pane == ActivePane::Outline {
        app.theme.border_focused
    } else {
        app.theme.border_unfocused
    };

    let outline_block = Block::default()
        .title(" Outline ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(outline_border));

    let outline_list = List::new(items)
        .block(outline_block)
        .highlight_style(Style::default().bg(app.theme.selected_bg).fg(app.theme.accent).add_modifier(Modifier::BOLD));

    f.render_stateful_widget(outline_list, main_chunks[0], &mut app.heading_state);

    // Right Pane (Content)
    let content_text = if app.selected_idx < app.doc.headings.len() {
        let h = &app.doc.headings[app.selected_idx];
        format!("# {}\n\n{}", h.title, h.raw_content)
    } else {
        "No content".to_string()
    };

    let content_border = if app.active_pane == ActivePane::Content {
        app.theme.border_focused
    } else {
        app.theme.border_unfocused
    };

    let content_block = Block::default()
        .title(" Content ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(content_border));

    let content_paragraph = Paragraph::new(content_text)
        .block(content_block)
        .wrap(Wrap { trim: false });

    f.render_widget(content_paragraph, main_chunks[1]);

    // Bottom Bar (Status/Help)
    let status_text = " q: Quit | Tab: Switch Pane | /: Search | j/k: Navigate | g/G: Top/Bottom";
    let bottom_bar = Paragraph::new(status_text).style(Style::default().bg(app.theme.selected_bg).fg(app.theme.fg));
    f.render_widget(bottom_bar, chunks[2]);
}
EOF"}

