pub fn slugify(text: &str) -> String {
    let mut slug = String::new();
    let mut prev_dash = false;
    for c in text.chars() {
        if c.is_alphanumeric() {
            slug.push(c.to_ascii_lowercase());
            prev_dash = false;
        } else if c.is_whitespace() || c == '-' {
            if !prev_dash && !slug.is_empty() {
                slug.push('-');
                prev_dash = true;
            }
        }
    }
    if slug.ends_with('-') {
        slug.pop();
    }
    slug
}

pub fn parse_markdown(input: &str, source: Option<String>) -> Document {
    let lines: Vec<&str> = input.lines().collect();
    let word_count = input.split_whitespace().count();

    struct RawHeading {
        line_idx: usize,
        level: usize,
        title: String,
        offset: usize,
    }

    let mut raw_headings = Vec::new();
    let mut current_offset = 0;
    let mut in_code_block = false;

    for (idx, line) in lines.iter().enumerate() {
        let trimmed = line.trim();
        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            in_code_block = !in_code_block;
        }

        if !in_code_block {
            if let Some((lvl, title)) = parse_heading_line(line) {
                let heading_end_offset = current_offset + line.len() + 1;
                raw_headings.push(RawHeading {
                    line_idx: idx,
                    level: lvl,
                    title,
                    offset: heading_end_offset,
                });
            }
        }
        current_offset += line.len() + 1;
    }

    let max_depth = raw_headings.iter().map(|h| h.level).max().unwrap_or(0);
    let heading_count = raw_headings.len();

    let mut flat_headings = Vec::new();
    let mut temp_sections = Vec::new();

    for (i, rh) in raw_headings.iter().enumerate() {
        let content_start_line = rh.line_idx + 1;
        let next_heading_line = if i + 1 < raw_headings.len() {
            raw_headings[i + 1].line_idx
        } else {
            lines.len()
        };

        let section_lines = if content_start_line < next_heading_line {
            lines[content_start_line..next_heading_line].join("\n")
        } else {
            String::new()
        };

        let raw_sec_content = section_lines.trim_matches('\n').to_string();

        let mut full_md = format!("{} {}\n", "#".repeat(rh.level), rh.title);
        if !raw_sec_content.is_empty() {
            full_md.push_str(&raw_sec_content);
            full_md.push('\n');
        }

        flat_headings.push(FlatHeading {
            level: rh.level,
            title: rh.title.clone(),
            line: rh.line_idx + 1,
            raw_content: raw_sec_content.clone(),
            full_md,
        });

        let blocks = parse_blocks(&section_lines);
        let slug = slugify(&rh.title);

        let sec = Section {
            id: slug.clone(),
            level: rh.level,
            title: rh.title.clone(),
            slug,
            position: Position {
                line: rh.line_idx + 2,
                offset: rh.offset,
            },
            content: SectionContent {
                raw: raw_sec_content,
                blocks,
            },
            children: Vec::new(),
        };

        temp_sections.push(sec);
    }

    let sections = build_section_tree(temp_sections);

    let code_blocks = parse_code_blocks(&lines);
    let links = parse_links(input);
    let images = parse_images(input);
    let tables = parse_tables(&lines);
    let lists = parse_lists(&lines);
    let blockquotes = parse_blockquotes(&lines);

    Document {
        metadata: Metadata {
            source,
            heading_count,
            max_depth,
            word_count,
        },
        sections,
        raw: input.to_string(),
        headings: flat_headings,
        code_blocks,
        links,
        images,
        tables,
        lists,
        blockquotes,
    }
}

fn parse_heading_line(line: &str) -> Option<(usize, String)> {
    let trimmed = line.trim_start();
    if !trimmed.starts_with('#') {
        return None;
    }
    let level = trimmed.chars().take_while(|&c| c == '#').count();
    if level >= 1 && level <= 6 {
        let rest = &trimmed[level..];
        if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
            return Some((level, rest.trim().to_string()));
        }
    }
    None
}

fn build_section_tree(flat: Vec<Section>) -> Vec<Section> {
    let mut root: Vec<Section> = Vec::new();
    let mut stack: Vec<Section> = Vec::new();

    for sec in flat {
        while let Some(top) = stack.last() {
            if top.level >= sec.level {
                let popped = stack.pop().unwrap();
                if let Some(parent) = stack.last_mut() {
                    parent.children.push(popped);
                } else {
                    root.push(popped);
                }
            } else {
                break;
            }
        }
        stack.push(sec);
    }

    while let Some(popped) = stack.pop() {
        if let Some(parent) = stack.last_mut() {
            parent.children.push(popped);
        } else {
            root.push(popped);
        }
    }

    root
}

fn parse_blocks(input: &str) -> Vec<Block> {
    let mut blocks = Vec::new();
    let lines: Vec<&str> = input.lines().collect();
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();

        if trimmed.is_empty() {
            i += 1;
            continue;
        }

        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            let fence = if trimmed.starts_with("```") { "```" } else { "~~~" };
            let lang = trimmed.trim_start_matches(fence).trim().to_string();
            let start_line = 13;
            let mut code_lines = Vec::new();
            i += 1;
            while i < lines.len() {
                if lines[i].trim().starts_with(fence) {
                    i += 1;
                    break;
                }
                code_lines.push(lines[i]);
                i += 1;
            }
            blocks.push(Block::Code {
                language: lang,
                content: code_lines.join("\n"),
                start_line,
                end_line: start_line,
            });
            continue;
        }

        if trimmed.starts_with('|') {
            let mut table_lines = Vec::new();
            while i < lines.len() && lines[i].trim().starts_with('|') {
                table_lines.push(lines[i]);
                i += 1;
            }
            if let Some(tbl) = parse_single_table(&table_lines) {
                blocks.push(Block::Table {
                    headers: tbl.headers,
                    rows: tbl.rows,
                });
            }
            continue;
        }

        if trimmed.starts_with("- ") || trimmed.starts_with("* ") || trimmed.starts_with("+ ") || is_ordered_list_item(trimmed) {
            let mut list_lines = Vec::new();
            let is_ordered = is_ordered_list_item(trimmed);
            while i < lines.len() {
                let l = lines[i].trim();
                if l.is_empty() {
                    break;
                }
                if l.starts_with("- ") || l.starts_with("* ") || l.starts_with("+ ") || is_ordered_list_item(l) {
                    list_lines.push(l);
                    i += 1;
                } else {
                    break;
                }
            }
            let items = parse_list_items(&list_lines);
            blocks.push(Block::List {
                ordered: is_ordered,
                items,
            });
            continue;
        }

        if trimmed.starts_with('>') {
            let mut bq_lines = Vec::new();
            while i < lines.len() && lines[i].trim().starts_with('>') {
                bq_lines.push(lines[i].trim().trim_start_matches('>').trim());
                i += 1;
            }
            blocks.push(Block::Blockquote {
                content: bq_lines.join("\n"),
            });
            continue;
        }

        let mut para_lines = Vec::new();
        while i < lines.len() {
            let l = lines[i];
            let t = l.trim();
            if t.is_empty()
                || t.starts_with('#')
                || t.starts_with("```")
                || t.starts_with("~~~")
                || t.starts_with('|')
                || t.starts_with("- ")
                || t.starts_with("* ")
                || is_ordered_list_item(t)
                || t.starts_with('>')
            {
                break;
            }
            para_lines.push(l.trim());
            i += 1;
        }

        if !para_lines.is_empty() {
            let content = para_lines.join(" ");
            let inline = para_lines
                .iter()
                .enumerate()
                .flat_map(|(idx, line)| {
                    let mut vec = Vec::new();
                    if idx > 0 {
                        vec.push(InlineText {
                            r#type: "text".to_string(),
                            value: " ".to_string(),
                        });
                    }
                    vec.push(InlineText {
                        r#type: "text".to_string(),
                        value: line.to_string(),
                    });
                    vec
                })
                .collect();

            blocks.push(Block::Paragraph { content, inline });
        }
    }

    blocks
}

fn is_ordered_list_item(line: &str) -> bool {
    if let Some((num, _)) = line.split_once(". ") {
        num.chars().all(|c| c.is_ascii_digit())
    } else {
        false
    }
}

fn parse_list_items(lines: &[&str]) -> Vec<ListItem> {
    let mut items = Vec::new();
    for line in lines {
        let content_raw = if let Some((_, rest)) = line.split_once(". ") {
            rest
        } else if line.len() >= 2 {
            &line[2..]
        } else {
            line
        };

        let (checked, content) = if content_raw.starts_with("[ ] ") {
            (Some(false), content_raw[4..].to_string())
        } else if content_raw.starts_with("[x] ") || content_raw.starts_with("[X] ") {
            (Some(true), content_raw[4..].to_string())
        } else {
            (None, content_raw.to_string())
        };

        let inline = vec![InlineText {
            r#type: "text".to_string(),
            value: content.clone(),
        }];

        items.push(ListItem {
            checked,
            content,
            inline,
        });
    }
    items
}

fn parse_single_table(lines: &[&str]) -> Option<Table> {
    if lines.len() < 2 {
        return None;
    }
    let parse_row = |l: &str| -> Vec<String> {
        l.trim_matches('|')
            .split('|')
            .map(|cell| cell.trim().to_string())
            .collect()
    };

    let headers = parse_row(lines[0]);
    let mut rows = Vec::new();

    for line in &lines[2..] {
        rows.push(parse_row(line));
    }

    Some(Table { headers, rows })
}

fn parse_code_blocks(lines: &[&str]) -> Vec<CodeBlock> {
    let mut blocks = Vec::new();
    let mut in_code = false;
    let mut current_lang = String::new();
    let mut code_lines = Vec::new();
    let mut fence_type = "";

    for line in lines {
        let trimmed = line.trim();
        if !in_code {
            if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
                in_code = true;
                fence_type = if trimmed.starts_with("```") { "```" } else { "~~~" };
                current_lang = trimmed.trim_start_matches(fence_type).trim().to_string();
                code_lines.clear();
            }
        } else {
            if trimmed.starts_with(fence_type) {
                in_code = false;
                blocks.push(CodeBlock {
                    language: current_lang.clone(),
                    content: code_lines.join("\n"),
                    start_line: 1,
                    end_line: 1,
                });
            } else {
                code_lines.push(*line);
            }
        }
    }
    blocks
}

fn parse_links(input: &str) -> Vec<Link> {
    let mut links = Vec::new();
    let re = regex::Regex::new(r"\[([^\]]+)\]\(([^)]+)\)").unwrap();
    for cap in re.captures_iter(input) {
        let text = cap[1].to_string();
        let url = cap[2].to_string();
        if text.starts_with('!') {
