use clap::{Arg, ArgAction, Command, ValueHint};
use config::Config;
use markdown::*;
use std::env;
use std::fs;
use std::io::{self, Read};
use std::path::Path;

fn build_cli() -> Command {
    Command::new("treemd")
        .version("0.5.7")
        .about("treemd - A modern markdown viewer combining tree-based navigation with interactive TUI.\n\nLaunch without flags for interactive mode with dual-pane interface, vim-style navigation,\nsyntax highlighting, and real-time search. Use flags for CLI mode to extract, filter,\nand analyze markdown structure.\n\nExamples:\n  treemd README.md              # Interactive TUI mode\n  treemd -l README.md           # List all headings\n  treemd --tree README.md       # Show heading tree\n  treemd -s Installation doc.md # Extract section\n  treemd --setup-completions    # Set up shell completions")
        .arg(
            Arg::new("file")
                .help("Markdown file(s) to view (.md or .markdown), directory, or '-' for stdin\n\nPath to the markdown file(s) to open. Use '-' to read from stdin. If a directory is specified, opens file picker in that directory. Multiple files can be specified for the file picker. If no file is specified and stdin is piped, input is read from stdin.\n\nExamples: treemd README.md         # Open file treemd .                 # Open file picker in current directory treemd docs/             # Open file picker in docs directory treemd *.md              # Open file picker with matched files treemd -                 # Read from stdin cat doc.md | treemd -l   # Pipe markdown")
                .value_name("FILE")
                .action(ArgAction::Append)
                .value_hint(ValueHint::AnyPath),
        )
        .arg(
            Arg::new("list")
                .short('l')
                .long("list")
                .help("List all headings in the document (non-interactive)\n\nDisplays all headings with their level indicators (# for h1, ## for h2, etc.). Combine with --filter or --level to narrow results.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("tree")
                .long("tree")
                .help("Show heading tree structure with box-drawing characters (non-interactive)\n\nRenders the document structure as a visual tree using Unicode box-drawing. Shows parent-child relationships between headings hierarchically.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("filter")
                .long("filter")
                .help("Filter headings by text pattern (case-insensitive)\n\nOnly shows headings containing the specified text. Works with --list or --tree modes.\n\nExample: --filter \"install\" matches \"Installation\" and \"Installing\"")
                .value_name("PATTERN"),
        )
        .arg(
            Arg::new("level")
                .short('L')
                .long("level")
                .help("Show only headings at specific level (1-6)\n\nFilters headings by their level: 1 = # (h1), 2 = ## (h2), 3 = ### (h3), etc.\n\nExample: -L 2 shows only ## headings")
                .value_name("LEVEL")
                .value_parser(clap::value_parser!(usize)),
        )
