        out.push_str(&format!("links: {}\n", doc.links.len()));
        out.push_str(&format!("images: {}\n", doc.images.len()));
        out.push_str(&format!("tables: {}\n", doc.tables.len()));
        out.push_str(&format!("lists: {}\n", doc.lists.len()));
        out.push_str(&format!("words: {}", doc.metadata.word_count));
        return Ok(QueryValue::Strings(vec![out]));
    }

    if pipe == "levels" {
        let mut counts = [0usize; 7];
