                        .help("Line number in the markdown file\n\nThe line number to search for. Returns the heading at or immediately before this line.")
                        .value_name("LINE")
                        .required(true)
                        .value_parser(clap::value_parser!(usize)),
                ),
        )
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    if let Ok(comp) = env::var("COMPLETE") {
        let mut cmd = build_cli();
        match comp.as_str() {
            "bash" => clap_complete::generate(clap_complete::Shell::Bash, &mut cmd, "treemd", &mut io::stdout()),
            "zsh" => clap_complete::generate(clap_complete::Shell::Zsh, &mut cmd, "treemd", &mut io::stdout()),
            "fish" => clap_complete::generate(clap_complete::Shell::Fish, &mut cmd, "treemd", &mut io::stdout()),
            _ => {}
        }
        return Ok(());
    }

    let matches = build_cli().get_matches();

    if matches.get_flag("query_help") {
        print_query_help();
        return Ok(());
    }

    if matches.get_flag("setup_completions") {
        completions::setup_completions();
        return Ok(());
    }

    let files: Vec<String> = matches
        .get_many::<String>("file")
        .map(|vals| vals.cloned().collect())
        .unwrap_or_default();

    if let Some(("at-line", _sub_m)) = matches.subcommand() {
        return Ok(());
    }

    let is_cli = matches.get_flag("list")
        || matches.get_flag("tree")
        || matches.get_one::<String>("section").is_some()
        || matches.get_flag("count")
        || matches.get_one::<String>("query").is_some();

    if !is_cli {
        let mut cfg = Config::load();
        if let Some(theme) = matches.get_one::<String>("theme") {
            cfg.theme = theme.clone();
        }

        let (doc_input, source) = load_input(&files)?;
        let doc = parse_markdown(&doc_input, source);

        if let Err(e) = tui::run_tui(doc, &cfg) {
            eprintln!(
                "Failed to enable raw mode: {}. Interactive mode requires a terminal.\nNote: When piping input, ensure you have a controlling terminal.\nError: \n   0: \x1b[91m{}\x1b[0m\n\nLocation:\n   src/main.rs:275\n",
                e, e
            );
            std::process::exit(1);
        }
        return Ok(());
    }

    let (doc_input, source) = load_input(&files)?;
    let doc = parse_markdown(&doc_input, source);

    if let Some(query) = matches.get_one::<String>("query") {
        let q_fmt = matches.get_one::<String>("query_output").map(|s| s.as_str());
        match tql::execute_query(&doc, query, q_fmt) {
            Ok(res) => {
                if !res.is_empty() {
                    println!("{}", res);
                }
            }
            Err(e) => {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
        return Ok(());
    }

    if let Some(sec_name) = matches.get_one::<String>("section") {
        let sec_lower = sec_name.to_lowercase();
        let target_slug = slugify(sec_name);

        if let Some((idx, h)) = doc.headings.iter().enumerate().find(|(_, h)| h.title.to_lowercase() == sec_lower || slugify(&h.title) == target_slug) {
            let mut sec_md = h.full_md.clone();
            for next_h in &doc.headings[idx + 1..] {
                if next_h.level <= h.level {
                    break;
                }
                sec_md.push_str(&next_h.full_md);
            }
            print!("{}", sec_md);
        } else {
            eprintln!("Section '{}' not found", sec_name);
            std::process::exit(1);
        }
        return Ok(());
    }

    if matches.get_flag("count") {
        let mut counts = [0usize; 7];
        for h in &doc.headings {
            if h.level >= 1 && h.level <= 6 {
                counts[h.level] += 1;
            }
        }
        println!("Heading counts:");
        for lvl in 1..=6 {
            if counts[lvl] > 0 {
                println!("  {}: {}", "#".repeat(lvl), counts[lvl]);
            }
        }
        println!("\nTotal: {}", doc.metadata.heading_count);
        return Ok(());
    }

    if matches.get_flag("tree") {
        let filter_pat = matches.get_one::<String>("filter").map(|s| s.to_lowercase());
        let level_flt = matches.get_one::<usize>("level").copied();

        print_tree_view(&doc, filter_pat.as_deref(), level_flt);
        return Ok(());
    }

    if matches.get_flag("list") {
        let output_fmt = matches.get_one::<String>("output").unwrap().as_str();
        let filter_pat = matches.get_one::<String>("filter").map(|s| s.to_lowercase());
        let level_flt = matches.get_one::<usize>("level").copied();

        match output_fmt {
            "json" => {
                let json_val = serde_json::to_string_pretty(&doc).unwrap();
                println!("{}", json_val);
            }
            "tree" => {
                println!("Use --tree for tree output");
            }
            _ => {
                for h in &doc.headings {
                    if let Some(lvl) = level_flt {
                        if h.level != lvl {
                            continue;
                        }
                    }
                    if let Some(ref pat) = filter_pat {
                        if !h.title.to_lowercase().contains(pat) {
                            continue;
                        }
                    }
                    println!("{} {}", "#".repeat(h.level), h.title);
                }
            }
        }
        return Ok(());
    }

    Ok(())
}

fn load_input(files: &[String]) -> Result<(String, Option<String>), Box<dyn std::error::Error>> {
    if files.is_empty() {
        return Ok(("# Select a file".to_string(), None));
    }

    if files.len() == 1 && files[0] == "-" {
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf)?;
        return Ok((buf, None));
    }

    let file_path = &files[0];
    let path = Path::new(file_path);
    if !path.exists() {
        eprintln!("Error reading input: I/O error: No such file or directory (os error 2)");
        std::process::exit(1);
    }

    let content = fs::read_to_string(path)?;
    Ok((content, Some(file_path.clone())))
}

fn print_tree_view(doc: &Document, filter: Option<&str>, level_flt: Option<usize>) {
    let mut filtered_headings: Vec<&FlatHeading> = doc.headings.iter().collect();

    if let Some(pat) = filter {
        filtered_headings.retain(|h| h.title.to_lowercase().contains(pat));
    }
    if let Some(lvl) = level_flt {
        filtered_headings.retain(|h| h.level == lvl);
    }

    for (i, h) in filtered_headings.iter().enumerate() {
        let branch = if i == filtered_headings.len() - 1 { "└──" } else { "├──" };
        let indent = if h.level <= 1 {
            String::new()
        } else {
            "   ".repeat(h.level - 1)
        };
        println!("{}{}{} {}", indent, branch, "#".repeat(h.level), h.title);
    }
}

fn print_query_help() {
    println!(
        r#"treemd Query Language (tql)

A jq-like query language for navigating and extracting markdown structure.

ELEMENT SELECTORS
    .h, .heading    All headings (any level)
    .h1 - .h6       Headings by level
    .code           All code blocks
    .code[rust]     Code blocks by language
    .link, .a       All links
    .link[external] External links only
    .img            All images
    .table          All tables
    .list           All lists
    .blockquote     All blockquotes

FILTERS & INDEXING
    .h2[Features]       Heading containing "Features" (fuzzy)
    .h2["Installation"] Heading with exact text
    .h2[0]              First h2
    .h2[-1]             Last h2
    .h2[1:3]            h2s at index 1 and 2
    .h2[:3]             First 3 h2s

HIERARCHY
    .h1 > .h2           Direct child h2s under h1s
    .h1 >> .code        Code blocks anywhere under h1s

PIPES
    .h2 | text          Get heading text (strips ##)
    [.h2] | count       Count all h2s
    .code | lang        Get code block languages
    .link | url         Get link URLs

COLLECTION FUNCTIONS
    count, length       Count elements (alias: len, size)
    first, last         First/last element (alias: head)
    limit(n), take(n)   First n elements
    skip(n), drop(n)    Skip first n elements
    nth(n)              Get element at index
    reverse             Reverse order
    sort                Sort alphabetically
    sort_by(key)        Sort by property
    unique              Remove duplicates
    flatten             Flatten nested arrays
    group_by(key)       Group elements by key
    min, max            Min/max numeric value
    add                 Sum numbers or concat strings

STRING FUNCTIONS
    text                Get text representation
    upper, lower        Case conversion
    trim                Strip whitespace
    split(sep)          Split by separator
    join(sep)           Join with separator
    replace(a, b)       Replace substring
    slugify             URL-friendly slug
    lines, words, chars Count lines/words/chars

FILTER FUNCTIONS
    select(cond)        Keep if condition true (alias: where, filter)
    contains(s)         Contains substring (alias: includes)
    startswith(s)       Starts with prefix
    endswith(s)         Ends with suffix
    matches(regex)      Matches regex pattern
    any, all            Check if any/all truthy
    not                 Negate boolean

CONTENT FUNCTIONS
    content             Section content (for headings)
    md                  Raw markdown
    url, href, src      Get URL/link/image source
    lang                Code block language

AGGREGATION FUNCTIONS
    stats               Document statistics
    levels              Heading count by level
    langs               Code block count by language
    types               Link types count

EXAMPLES
    # List all h2 headings
    treemd -q '.h2' doc.md

    # Get heading text only
    treemd -q '.h2 | text' doc.md

    # Count headings
    treemd -q '[.h2] | count' doc.md

    # First 5 headings
    treemd -q '[.h] | limit(5)' doc.md

    # Filter headings (three equivalent ways)
    treemd -q '.h | select(contains("API"))' doc.md
    treemd -q '.h | where(contains("API"))' doc.md
    treemd -q '.h[API]' doc.md

    # All Rust code blocks
    treemd -q '.code[rust]' doc.md

    # External link URLs
    treemd -q '.link[external] | url' doc.md

    # h2s under "Features" section
    treemd -q '.h1[Features] > .h2' doc.md

    # Group headings by level
    treemd -q '[.h] | group_by("level")' doc.md

    # Document statistics
    treemd -q '. | stats' doc.md

    # JSON output
    treemd -q '.h2' --query-output json doc.md

OUTPUT FORMATS (--query-output)
    plain       Human-readable text (default)
    json        Compact JSON
    json-pretty Pretty-printed JSON (alias: jsonp)
    jsonl       Line-delimited JSON (one per line)
    md          Raw markdown
    tree        Tree structure

For more details, see: https://github.com/epistates/treemd"#
    );
}
EOF"}
